    inline bool Readable(const void* address, size_t count)
    {
        if (!address || !count)
            return false;
        auto current = reinterpret_cast<uintptr_t>(address);
        if (count > UINTPTR_MAX - current)
            return false;
        auto end = current + count;
        while (current < end)
        {
            MEMORY_BASIC_INFORMATION region = {};
            if (!VirtualQuery(reinterpret_cast<const void*>(current), &region, sizeof(region)) || region.State != MEM_COMMIT || (region.Protect & (PAGE_GUARD | PAGE_NOACCESS)))
                return false;
            auto protection = region.Protect & 0xFF;
            if (protection != PAGE_READONLY && protection != PAGE_READWRITE && protection != PAGE_WRITECOPY && protection != PAGE_EXECUTE_READ && protection != PAGE_EXECUTE_READWRITE && protection != PAGE_EXECUTE_WRITECOPY)
                return false;
            auto base = reinterpret_cast<uintptr_t>(region.BaseAddress);
            if (region.RegionSize > UINTPTR_MAX - base || base + region.RegionSize <= current)
                return false;
            current = (base + region.RegionSize < end) ? base + region.RegionSize : end;
        }
        return true;
    }

    inline bool Matches(uintptr_t* refused = nullptr)
    {
        if (refused) *refused = 0;
        auto module = reinterpret_cast<const uint8_t*>(GetModuleHandleW(nullptr));
        // Only the supported executable is accepted; the image must cover every byte checked below.
        if (reinterpret_cast<uintptr_t>(module) != 0x400000 || !Readable(module, sizeof(IMAGE_DOS_HEADER)))
            return false;
        auto dos = reinterpret_cast<const IMAGE_DOS_HEADER*>(module);
        if (dos->e_magic != IMAGE_DOS_SIGNATURE || dos->e_lfanew <= 0 || dos->e_lfanew > 0x1000)
            return false;
        auto nt = reinterpret_cast<const IMAGE_NT_HEADERS32*>(module + dos->e_lfanew);
        if (!Readable(nt, sizeof(*nt)) || nt->Signature != IMAGE_NT_SIGNATURE || nt->FileHeader.Machine != IMAGE_FILE_MACHINE_I386 || nt->OptionalHeader.Magic != IMAGE_NT_OPTIONAL_HDR32_MAGIC || nt->OptionalHeader.SizeOfImage < 0x167E76)
            return false;
        for (const auto& prefix : Prefixes)
        {
            auto bytes = reinterpret_cast<const void*>(prefix.address);
            if (!Readable(bytes, prefix.bytes.size()) || std::memcmp(bytes, prefix.bytes.data(), prefix.bytes.size()) != 0)
            {
                if (refused) *refused = prefix.address;
                return false;
            }
        }
        return true;
    }
